from taf.collectors.core import StartableCollector
from taf.collectors.core.entities.executor import ExecutionError, TimeoutError
from taf.collectors.core.templates.dynamic_class_creation import Using
import time
import re
import tempfile
from io import open

import configparser
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class BtslogCollector(Using("tool_executor"),
                      Using("file_getter"),
                      Using("file_putter"),
                      StartableCollector):

    def __init__(
            self,
            btslog_path='/opt/btslog/btslog',
            btslog_launcher_path='/opt/btslog/btslog_launcher',
            log_dir=None,
            target_file_name=None,
            poll_interval=0.1,
            start_timeout=10,
            teardown_timeout=60,
            syslog_timeout=3,
            btslog_configuration=None,
            **kwargs):
        super(BtslogCollector, self).__init__(**kwargs)
        self._log_dir = log_dir
        self._btslog_path = btslog_path
        self._btslog_launcher_path = btslog_launcher_path
        self._sudo_prefix = None
        self._poll_interval = poll_interval
        self._start_timeout = start_timeout
        self._teardown_timeout = teardown_timeout
        self._syslog_timeout = syslog_timeout
        self._btslog_pid = None
        if target_file_name is None:
            target_file_name = "syslog_files.tgz"
        self._target_file_name = target_file_name
        self._btslog_configuration_file = None
        self._btslog_configuration = btslog_configuration
        self._btslog_configuration_bkp = tempfile.NamedTemporaryFile(prefix='btslog_ini_', suffix='.bkp')
        self._btslog_configuration_new = tempfile.NamedTemporaryFile(prefix='btslog_ini_', suffix='.new')

    def _current_time(self):
        return time.time()

    def _sleep(self, interval):
        time.sleep(interval)

    def _setup(self):
        self._sudo_prefix = self._tool_executor.sudo_prefix()
        try:
            self._tool_executor.execute(
                "{sudo_prefix}pkill -9 -f -x '{btslog_path} -NOGUI'".format(
                    sudo_prefix=self._sudo_prefix,
                    btslog_path=self._btslog_path).encode())
        except ExecutionError as exception:
            logger.debug("Terminating %r process failed: %r", self._btslog_path, exception)
        self._start_btslog()
        self._exit_btslog_run()
        if self._btslog_configuration:
            self._update_btslog_ini()
        if self._log_dir is None:
            self._log_dir = self._tool_executor.execute(
                "grep -oP '^SysLogFileTemplate=\\K.*(?=/SYSLOG)' {btslog_ini}".format(
                    btslog_ini=self._btslog_configuration_file).encode()).decode().strip()
        setup_cmd = "if [ -d '{log_dir}' ] ; then cd '{log_dir}' ; rm -f SYSLOG_* ; fi" \
            .format(log_dir=self._log_dir)
        self._tool_executor.execute(setup_cmd.encode())

        self._start_btslog()
        self._btslog_pid = self._get_btslog_pid()

    def _start_btslog(self):
        self._process = self._tool_executor.start(
            "'{btslog_path}' -NOGUI".format(btslog_path=self._btslog_path).encode(),
            use_tty=True)
        self._log_additional_process_logs_for_debug()
        self._extract_configuration_file_path_from_stdout()

    def _extract_configuration_file_path_from_stdout(self):
        start_time = self._current_time()
        output_buffer = b''

        while True:
            current_time = self._current_time()
            elapsed_time = current_time - start_time
            remaining_time = self._start_timeout - elapsed_time

            chunk = self._process.stdout.read_until_string(b"BTSLog> ", timeout=remaining_time)
            output_buffer += chunk

            match = re.search(rb"Used configuration (.*\.ini)", output_buffer)
            if match:
                self._btslog_configuration_file = match.group(1).decode().strip()
                logger.info(
                    "BTSLog startup completed successfully, config file: %s",
                    self._btslog_configuration_file)
                break

    def _start(self):
        start_cmd = "'{btslog_launcher}' start_udplog".format(btslog_launcher=self._btslog_launcher_path)
        self._tool_executor.execute(start_cmd.encode())
        self._log_additional_process_logs_for_debug()

    def _stop(self):
        self._log_additional_process_logs_for_debug()
        stop_cmd = "'{btslog_launcher}' stop_udplog".format(btslog_launcher=self._btslog_launcher_path)
        self._tool_executor.execute(stop_cmd.encode())
        self._wait_until_syslog_file_closed()

    def _teardown(self):
        self._exit_btslog_run()
        if self._btslog_configuration:
            self._revert_btslog_ini()
        self._btslog_configuration_bkp.close()
        self._btslog_configuration_new.close()

    def _exit_btslog_run(self):
        teardown_cmd = "'{btslog_launcher}' exit".format(btslog_launcher=self._btslog_launcher_path)
        output = self._tool_executor.execute(teardown_cmd.encode())
        assert b"Bye! Bye!\n" in output
        self._process.wait(timeout=self._teardown_timeout)
        self._process.stdout.read()
        self._process.stderr.read()


    def _collect(self, target_dir):
        syslog_file_collect = "cd '{log_path}' && find . -name 'SYSLOG*'".format(log_path=self._log_dir)
        syslog_files = " ".join(self._tool_executor.execute(syslog_file_collect.encode()).decode().strip().split("\n"))
        tar_file_cmd = "cd '{log_dir}' ; tar zcvf syslog_files.tgz {syslog_files}".format(
            log_dir=self._log_dir,
            syslog_files=syslog_files)
        self._tool_executor.execute(tar_file_cmd.encode())
        self._file_getter.get_file(source_path=self._log_dir + '/syslog_files.tgz',
                                   target_path=target_dir + '/{name}'.format(name=self._target_file_name))

    def _get_btslog_pid(self):
        get_btslog_pid_cmd = "pgrep -f -x '{btslog_path} -NOGUI'".format(
            btslog_path=self._btslog_path)
        try:
            pid_output = self._tool_executor.execute(get_btslog_pid_cmd.encode())
            return int(pid_output.rstrip())
        except ValueError:
            logger.info("unexpected/multiple PID value observed : %r", pid_output)
            self._log_additional_process_logs_for_debug()
            raise ValueError("unexpected PID value observed : {} \n"
                             "Please ensure single BTSLog collector instance at a time.\n"
                             "Ensure not to start or terminate BTSLog tool manually with"
                             " BTSLog collector instance".format(pid_output))

    def _log_additional_process_logs_for_debug(self):
        self._tool_executor.execute(
            "ps -o ppid,pid,pgid,sid,tty,tpgid,stat,uid,time,etime,pcpu,pmem,vsz,rss,command axfww".encode())
        self._tool_executor.execute(
            "{sudo_prefix}ss -aptun".format(sudo_prefix=self._sudo_prefix).encode())


    def _wait_until_syslog_file_closed(self):
        start_time = self._current_time()
        while not self._is_syslog_closed():
            self._sleep(self._poll_interval)
            current_time = self._current_time()
            elapsed_time = current_time - start_time
            remaining_time = self._syslog_timeout - elapsed_time
            if remaining_time <= 0:
                raise TimeoutError("Time-out in stopping syslog within {syslog_timeout} sec".format(
                    syslog_timeout=self._syslog_timeout))

    def _is_syslog_closed(self, exception_occurred=0):
        check_syslog_closed_cmd = r"ls -l /proc/{btslog_pid}/fd".format(
            btslog_pid=self._btslog_pid)
        try:
            output = self._tool_executor.execute(check_syslog_closed_cmd.encode())
            return sum(b"SYSLOG" in line for line in output.splitlines()) == 0
        except ExecutionError as exception:
            if exception_occurred < 3:
                logger.debug("Exception occurred {} time. Ignoring {}".format(exception_occurred + 1, exception))
                return self._is_syslog_closed(exception_occurred=exception_occurred + 1)
            raise

    def _update_btslog_ini(self):
        self._file_getter.get_file(source_path=self._btslog_configuration_file,
                                   target_path=self._btslog_configuration_bkp.name)
        config = configparser.ConfigParser(interpolation=None)
        config.optionxform = lambda option: option
        config.read_file(self._open(self._btslog_configuration_bkp.name))
        for section, option_dict in self._btslog_configuration.items():
            if not config.has_section(section):
                config.add_section(section)
            for option, value in option_dict.items():
                config.set(section, option, value)
        with self._open(self._btslog_configuration_new.name, "w") as config_file:
            config.write(config_file, space_around_delimiters=False)
        self._file_putter.put_file(source_path=self._btslog_configuration_new.name,
                                   target_path=self._btslog_configuration_file)

    def _open(self, *args):
        return open(*args)

    def _revert_btslog_ini(self):
        self._file_putter.put_file(source_path=self._btslog_configuration_bkp.name,
                                   target_path=self._btslog_configuration_file)
